use xiom.io;

use xiom.string;
interface Describable {
  fn label(&self) -> Str;

  fn describe(&self) -> Str {
    string.str_concat(self.label(), " - no description available")
  }
}

type Product = {
  name: Str;
}

fn Product.label(&self) -> Str {
  self.name.clone()
}

fn main() -> Int {
  let p = Product{ name: "Widget" };
  io.println(p.label());
  io.println(p.describe());
  return 0;
}
